mod common;

use axum::http::{Method, StatusCode};
use axum_bookclub::app;
use common::send;
use serde_json::json;

async fn make_club_and_book(router: &axum::Router) -> (u64, u64) {
    let (_, club) = send(router, Method::POST, "/api/clubs", Some(json!({"name": "C", "description": "x"}))).await;
    let club_id = club["id"].as_u64().unwrap();
    let (_, book) = send(
        router,
        Method::POST,
        &format!("/api/clubs/{club_id}/books"),
        Some(json!({"title": "T", "author": "A"})),
    )
    .await;
    (club_id, book["id"].as_u64().unwrap())
}

#[tokio::test]
async fn bulk_status_applies_all_when_every_id_is_valid() {
    let router = app();
    let (_, book1) = make_club_and_book(&router).await;
    let (_, book2) = make_club_and_book(&router).await;

    let (status, body) = send(
        &router,
        Method::POST,
        "/api/books/bulk-status",
        Some(json!({"book_ids": [book1, book2], "status": "reading"})),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(body["books"].as_array().unwrap().len(), 2);
}

#[tokio::test]
async fn bulk_status_rejects_whole_batch_on_one_bad_id() {
    let router = app();
    let (club_id, book1) = make_club_and_book(&router).await;

    let (status, _) = send(
        &router,
        Method::POST,
        "/api/books/bulk-status",
        Some(json!({"book_ids": [book1, 999999], "status": "reading"})),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST);

    let (_, books) = send(&router, Method::GET, &format!("/api/clubs/{club_id}/books"), None).await;
    let book = books.as_array().unwrap().iter().find(|b| b["id"].as_u64().unwrap() == book1).unwrap();
    assert_eq!(book["status"], "to_read", "book before the bad id must be UNCHANGED");
}

